import{_ as t}from"./chunks/theme.Dl-T8ALT.js";import{c as o,$ as n,Q as s,j as i,g as a,o as l,n as c,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"About the Developers","description":"The background of OmniCraft ERP, craft workshop origins, and practical engineering principles.","frontmatter":{"title":"About the Developers","description":"The background of OmniCraft ERP, craft workshop origins, and practical engineering principles.","order":18,"aside":false,"lastUpdated":false,"pageClass":"page-no-date","datePublished":"2026-11-14"},"headers":[],"relativePath":"docs/about.md","filePath":"docs/about.md"}'),p={name:"docs/about.md"},u={id:"about-the-developers",tabindex:"-1"};function h(g,e,f,m,b,k){const r=n("DocIcon");return s(),i("div",null,[a("h1",u,[l(r,{name:"about"}),e[0]||(e[0]=c(" About the Developers ",-1)),e[1]||(e[1]=a("a",{class:"header-anchor",href:"#about-the-developers","aria-label":'Permalink to "About the Developers"'},"​",-1))]),e[2]||(e[2]=d('<p><strong>OmniCraft ERP</strong> was created inside an active craft workshop—amidst machinery, tools, and real materials where structural reliability and practical usability are tested every day.</p><div class="maker-profile-card"><div class="maker-avatar-wrap"><img src="'+t+'" alt="Nick Murashkin — founder of N. Murashkin workshop and creator of OmniCraft ERP" class="maker-avatar-img"><span class="maker-avatar-badge">Maker &amp; Architect</span></div><div class="maker-info"><h3 class="maker-name">Nick Murashkin</h3><p class="maker-role">Founder of <strong>N. Murashkin Workshop</strong> and author of <strong>OmniCraft ERP</strong></p><p class="maker-quote">&quot;The software was originally built to serve the practical needs of our own business and workshop: we needed to eliminate manual spreadsheet math, accurately track product costs, and keep finances completely clear. The system is built on operational workflows that run in our daily craft practice.&quot;</p><div class="maker-links"><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"></path></svg> Releases Repository </a><a href="/docs/contacts" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path></svg> Contacts &amp; Details </a></div></div></div><hr><h2 id="engineering-principles" tabindex="-1">Engineering Principles <a class="header-anchor" href="#engineering-principles" aria-label="Permalink to &quot;Engineering Principles&quot;">​</a></h2><p>In both workshop craft and software engineering, we follow a single standard: an operational tool must be dependable, predictable, and built to last.</p><p>OmniCraft ERP was engineered as a practical system for independent makers and entrepreneurs, built on four core principles:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Data Storage Reliability:</strong><br> A local database with automatic save for every operation and multi-tier backups protects records against hardware failures or power loss. </div></li><li><span class="craft-list-bullet"></span><div><strong>Local Storage and Autonomy:</strong><br> Customer records, financial ledgers, inventory balances, and production recipes reside directly on your machine. The software runs without requiring an internet connection and operates independently of remote cloud servers. </div></li><li><span class="craft-list-bullet"></span><div><strong>Perpetual Ownership:</strong><br> You acquire the software for a selected period or permanently. Access to your business records is never locked behind recurring monthly subscription fees. </div></li><li><span class="craft-list-bullet"></span><div><strong>Transparent Cost Calculations:</strong><br> The system computes raw material costs using moving average costing, accounting for machinery depreciation, operational overhead, and actual labor time. </div></li></ul><hr><h2 id="background-and-origins" tabindex="-1">Background and Origins <a class="header-anchor" href="#background-and-origins" aria-label="Permalink to &quot;Background and Origins&quot;">​</a></h2><p>Before developing this system, accounting in the workshop relied on spreadsheets and notebooks. Calculating the true cost of an item—factoring in raw material shipping, machinery depreciation, and labor hours—either required repetitive manual calculations or rough estimates.</p><p>Daily operations called for a dedicated tool designed for practical business tasks:</p><ol><li><strong>Material Cost Accounting:</strong> automated recalculation of inventory values using moving average costing, freight cost distribution, and automatic stock deduction upon order completion.</li><li><strong>Expense and Break-Even Tracking:</strong> clear calculation of break-even thresholds, hourly labor rates, and overhead distribution.</li><li><strong>Data Control and Security:</strong> working with a local database without exposure to external service policy changes or third-party data collection.</li></ol><p>This led to the creation of OmniCraft ERP—an accounting system built for craft workshops, service centers, and small manufacturing businesses.</p><hr><h2 id="technical-architecture" tabindex="-1">Technical Architecture <a class="header-anchor" href="#technical-architecture" aria-label="Permalink to &quot;Technical Architecture&quot;">​</a></h2><p>The platform is engineered according to standards for dependable desktop application software:</p><ul><li><strong>Local Database Engine:</strong> the self-contained embedded database delivers fast responsiveness on your machine without requiring external server installations.</li><li><strong>Autonomy:</strong> zero hidden tracking or background transmission of customer rosters and financial records to remote servers.</li><li><strong>Public Release Track:</strong> software updates, changelogs, and binary checksums are published in the open GitHub repository.</li></ul><hr><h2 id="contact-and-feedback" tabindex="-1">Contact and Feedback <a class="header-anchor" href="#contact-and-feedback" aria-label="Permalink to &quot;Contact and Feedback&quot;">​</a></h2><p>We continue to develop the system based on daily workshop practice and feedback from manufacturing and service professionals.</p><p>To submit feature proposals, report feedback, or get in touch:</p><ul><li><strong>Official Website:</strong> <a href="https://omnicraft-erp.com" target="_blank" rel="noreferrer">omnicraft-erp.com</a></li><li><strong>Releases Repository:</strong> <a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noreferrer">OmniCraft-ERP-Releases (GitHub)</a></li><li><strong>Contacts &amp; Legal Details:</strong> <a href="/docs/contacts">Contacts Page</a></li></ul>',22))])}const C=o(p,[["render",h]]);export{y as __pageData,C as default};
